 strategy=[("2차전지 캔·양극박", "원통형 캔·양극박 증설로 성장", "원통형 46파이 셀(LG엔솔·삼성SDI) 양산 일정이 수요 근거예요. 테슬라·전기차 수요 둔화로 늦어질 수 있어요.", "보통"),
           ("수익성 회복", "중장기 목표 15%+α", "본업(포장재)은 안정적이에요. 신사업 가동률이 오르기 전까지 목표 달성은 어려워요.", "보통")],
